import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useSelector } from 'react-redux';
import api from '../api/axios';
import { Container, Card, Row, Col, Image, Button, Alert, Spinner, Badge } from 'react-bootstrap';

const TeacherDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [teacher, setTeacher] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const roles = useSelector(state => state.auth.roles || []);
  const isDirector = roles.includes('Директор');

  useEffect(() => {
    fetchTeacher();
  }, [id]);

  const fetchTeacher = async () => {
    setLoading(true);
    try {
      // Используем публичный маршрут /api/teachers/:id
      const res = await api.get(`/teachers/${id}`);
      setTeacher(res.data);
    } catch (err) {
      setError(err.response?.data?.message || 'Ошибка загрузки данных учителя');
    } finally {
      setLoading(false);
    }
  };

  const copyToClipboard = (text) => {
    if (text) {
      navigator.clipboard?.writeText(text);
      alert('Скопировано в буфер обмена!');
    }
  };

  if (loading) {
    return (
      <Container className="text-center mt-5">
        <Spinner animation="border" variant="primary" />
        <p>Загрузка...</p>
      </Container>
    );
  }

  if (error) {
    return (
      <Container className="mt-4">
        <Alert variant="danger">{error}</Alert>
        <Button variant="secondary" onClick={() => navigate('/teachers')}>
          ← Назад к списку учителей
        </Button>
      </Container>
    );
  }

  if (!teacher) {
    return (
      <Container className="mt-4">
        <Alert variant="warning">Учитель не найден</Alert>
        <Button variant="secondary" onClick={() => navigate('/teachers')}>
          ← Назад к списку учителей
        </Button>
      </Container>
    );
  }

  return (
    <Container className="mt-4">
      <Button variant="secondary" className="mb-3" onClick={() => navigate('/teachers')}>
        ← Назад к списку учителей
      </Button>
      
      <h2>Информация об учителе</h2>
      
      <Row>
        <Col md={3}>
          <Image
            src={`http://localhost:8080/uploads/${teacher.avatar || 'default.png'}`}
            rounded
            fluid
            style={{ borderRadius: '15px' }}
          />
        </Col>
        <Col md={9}>
          <Card>
            <Card.Body>
              <h4>{teacher.last_name} {teacher.first_name} {teacher.middle_name}</h4>
              
              <hr />
              
              <Row>
                <Col md={6}>
                  <p><strong>Должность:</strong> {teacher.position || 'Не указана'}</p>
                  <p><strong>Email:</strong> {teacher.email}</p>
                  <p><strong>Телефон:</strong> {teacher.phone || 'Не указан'}</p>
                </Col>
                <Col md={6}>
                  <p><strong>Школа:</strong> {teacher.school_name || 'Не указана'}</p>
                  <p><strong>Классы:</strong> {teacher.taught_classes?.length > 0 
                    ? teacher.taught_classes.sort((a,b) => a-b).map(c => (
                        <Badge key={c} bg="info" className="me-1">{c} класс</Badge>
                      ))
                    : 'Не назначен'
                  }</p>
                </Col>
              </Row>

              {teacher.subjects && teacher.subjects.length > 0 && (
                <>
                  <hr />
                  <h5>📚 Преподаваемые предметы</h5>
                  <div className="mb-3">
                    {teacher.subjects.map(subj => (
                      <Badge key={subj.id} bg="success" className="me-2 p-2">
                        {subj.name}
                      </Badge>
                    ))}
                  </div>
                </>
              )}

              {isDirector && (
                <>
                  <hr />
                  <h5>🔐 Данные для входа (только для директора)</h5>
                  <Row>
                    <Col md={6}>
                      <p>
                        <strong>Логин:</strong>{' '}
                        <code 
                          style={{ cursor: 'pointer' }} 
                          onClick={() => copyToClipboard(teacher.login)}
                          title="Нажмите, чтобы скопировать"
                        >
                          {teacher.login}
                        </code>
                      </p>
                    </Col>
                    <Col md={6}>
                      <p>
                        <strong>Пароль:</strong>{' '}
                        <code 
                          style={{ cursor: 'pointer', backgroundColor: '#f0f0f0', padding: '2px 8px', borderRadius: '4px' }}
                          onClick={() => copyToClipboard(teacher.plain_password)}
                          title="Нажмите, чтобы скопировать"
                        >
                          {teacher.plain_password || 'Не установлен'}
                        </code>
                      </p>
                    </Col>
                  </Row>
                  <small className="text-muted">
                    💡 Нажмите на логин или пароль, чтобы скопировать
                  </small>
                </>
              )}

              {!isDirector && (
                <Alert variant="secondary" className="mt-3">
                  <small>📌 Логин и пароль доступны только для директора</small>
                </Alert>
              )}

              <hr />
              <Button variant="outline-primary" onClick={() => navigate('/teachers')}>
                Вернуться к списку
              </Button>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default TeacherDetail;
